import json, pathlib, datetime
root=pathlib.Path('.job-search/research/2026-10-16-wise-ai')
old=json.loads((root/'live-job-before.json').read_text())
now=datetime.datetime.now(datetime.timezone.utc).isoformat().replace('+00:00','Z')
def req(key,text,essential,assessment,evidence,explanation):
 return dict(id='wise-review-'+key,text=text,essential=essential,assessment=assessment,evidenceIds=evidence,explanation=explanation)
requirements=[
 req('fullstack','Fullstack JavaScript / React / Node development',True,'met',['ev-react','ev-backend','ev-confirmed-ts-next'],'Candidate reports production React, TypeScript, Node and Express work across web products; four years TypeScript and Next.js.'),
 req('zoom','Prior ZoomApps experience',True,'unknown',[],'The listing explicitly marks ZoomApps as mandatory. No Zoom Apps SDK or shipped ZoomApp project appears in the canonical facts or candidate confirmations. Unreported experience is not proof of absence.'),
 req('api','API development',True,'met',['ev-backend','ev-integration'],'Reported Express/MongoDB backend includes approximately 1,000 endpoints and third-party integrations. These are candidate-reported figures.'),
 req('systems','System design, databases and performance optimization',True,'met',['ev-backend','ev-performance','ev-product','ev-confirmed-sql'],'Shared backend and school-scoped data, production product ownership, MongoDB/SQL and documented query/frontend optimization provide concrete evidence for these broad requirements.'),
 req('ui','Responsive product interfaces',True,'met',['ev-react','ev-frontend-foundations'],'React/TypeScript product interfaces, reusable components and Tailwind work support the broad frontend requirement.'),
 req('cloud','Cloud platforms and DevOps familiarity',True,'met',['ev-git-deploy','ev-confirmed-docker'],'DigitalOcean/Vercel deployment, CI/CD and Docker provide evidence of general cloud/DevOps familiarity. AWS/GCP were examples in the listing; no provider-specific expertise is claimed.'),
 req('ownership','Startup problem solving and cross-functional communication',True,'met',['ev-product','ev-remote','ev-confirmed-english'],'Candidate reports small-team leadership, international remote delivery and direct founder collaboration; advanced English is self-reported.'),
 req('education','Relevant degree or equivalent experience',True,'met',['ev-experience','ev-product'],'The JD accepts equivalent experience. Candidate has no completed degree; four-plus calendar years of product delivery are the basis for this mapping, not a degree claim.'),
 req('health','Healthtech experience',False,'unknown',[],'The listing describes this as a plus. No healthcare-specific work is established in candidate facts.'),
 req('ml','Computer vision and signal-processing background / current stack',False,'unknown',[],'The advertised stack includes Python/FastAPI, OpenCV, MediaPipe, PyTorch/TensorFlow, SciPy and NumPy under a flexible current-direction heading. Candidate AI experience is product/API integration, not established CV or signal-processing research.'),
 req('providers','AWS or GCP-specific experience',False,'unknown',[],'No AWS/GCP experience is confirmed. Docker and DigitalOcean do not establish these provider-specific skills.')
]
def source(key,label,url,text):
 return dict(id='wise-review-'+key,label=label,url=url,text=text,capturedAt=now,screenshotUrl='',screenshotPath='')
sources=[
 source('employer','Official employer product site','https://www.wiseai.care/','Boston contactless-vitals product with a ZoomApp guide. Employer footer links the Harvard founder story and the wiseaicare LinkedIn company. Publishes contact@wiseai.care as general contact; no careers link or vacancy found on the reviewed homepage.'),
 source('job','Live Himalayas vacancy (secondary source)','https://himalayas.app/companies/wise-ai/jobs/title-founding-engineer-fullstack-zoom-app','Full-time remote; Pakistan included. Advertises USD 12,000–24,000 annually plus potential equity. ZoomApps is mandatory; requests an intro, portfolio/GitHub and 1–2 ZoomApp examples at founders@wiseai.care. Listing dates are October 11–December 10, 2026; these are board dates, not employer confirmation.'),
 source('wellfound','Matching Wellfound vacancy unavailable','https://wellfound.com/jobs/3641018-founding-engineer-fullstack-zoom-app','Matching job is indexed with salary and equity, but direct web retrieval returned HTTP 410 Gone. Indexed text does not establish a current opening; original source relationship is not proven.'),
 source('acquisition','Harvard alumni announcement','https://hsph.harvard.edu/alumni-friends/news/alumni-news-summer-2026/','Page last updated July 16, 2026 reports that cofounders Annanya Panagala and Mateusz Firlej announced Wise AI was acquired by Theris. This creates a reason to re-confirm recruiting status; acquisition alone does not prove this role closed.'),
 source('identity','Company LinkedIn linked from employer footer','https://www.linkedin.com/company/wiseaicare/?viewAsMember=true','Boston health-monitoring company, with Annanya Panagala and Mateusz Firlej listed. Distinct from the similarly named Malaysian identity-verification business; Built In company profile metadata must not be combined with this employer.')
]
research=dict(companyUrl='https://www.wiseai.care/',contacts=[dict(id='wise-review-annanya',name='Annanya Panagala',role='Cofounder (Harvard announcement); publicly listed Wise AI team member',profileUrl='https://www.linkedin.com/in/annanya-panagala',sourceUrl='https://www.linkedin.com/company/wiseaicare/?viewAsMember=true',referralRoute='Public LinkedIn profile only; no personal introduction or referral relationship verified. Job board publishes founders@wiseai.care for applications.',notes='Current recruiting ownership after the Theris acquisition is unconfirmed. Do not infer a private email or internal referral.',capturedAt=now)],sources=sources)
notes='Review 2026-10-16: Not application-ready. Mandatory ZoomApps experience and the requested 1–2 ZoomApp examples are unconfirmed. Official company site is verified, but a current employer vacancy was not found: matching Wellfound URL returned 410 and Harvard reports acquisition by Theris (July 2026 update). Himalayas still advertises Pakistan remote eligibility and USD 12k–24k salary plus equity; those are board claims, not a confirmed current contract. No salary-based exclusion: candidate USD 50k expectation is negotiable. General employer contact is contact@wiseai.care; founders@wiseai.care comes from the job description. No application or outreach performed.'
patch=dict(priority='low',fit='unknown',eligibility='unknown',eligibilityEvidence='Live Himalayas listing explicitly includes Pakistan. Current eligibility is not independently confirmed by an employer vacancy after the reported acquisition; retain unknown pending current employer confirmation.',requirements=requirements,research=research,contactEmail='founders@wiseai.care',notes=notes,nextAction='Hold application. First establish whether the candidate has genuine ZoomApps work and 1–2 shareable examples, then verify that Wise AI/Theris is still hiring this role and accepts Pakistan-based remote employment.',tags=list(dict.fromkeys(old['job'].get('tags',[])+['reviewed-2026-10-16','zoomapps-required','current-opening-unconfirmed'])))
action=[dict(type='update_job',id=old['job']['id'],patch=patch)]
(root/'proposed-update.json').write_text(json.dumps(action,indent=2)+'\n')
review=dict(schemaVersion=1,capturedAt=now,jobId=old['job']['id'],conclusion='Hold: essential ZoomApps evidence missing and present employer hiring status unconfirmed.',applicationReady=False,currentOpening=dict(aggregatorLive=True,employerConfirmed=False,wellfoundResult='410 Gone via web retrieval',acquisition='Harvard source updated July 16, 2026 reports acquisition by Theris',inference='Board freshness cannot establish current employer headcount; do not label closed solely from acquisition.'),compensation=dict(advertisedCurrency='USD',advertisedAnnualMin=12000,advertisedAnnualMax=24000,equityAdvertised=True,equityOnly=False,paidStatus='Advertised paid role; present employer salary/contract unconfirmed',candidateExpectationNotFloor=True),eligibility=dict(boardIncludesPakistan=True,currentEmployerConfirmation=False,assessment='unknown'),applicationRoute=dict(method='Email or message per public JD',address='founders@wiseai.care',sourceUrl=sources[1]['url'],officialGeneralContact='contact@wiseai.care',requiredMaterials=['Short introduction','GitHub or portfolio; papers only if any','1–2 projects involving a ZoomApp'],additionalQuestions='No employer application questionnaire verified. Himalayas Apply now redirects to job-seeker sign-up.',submitted=False),missingFacts=['Does candidate have actual ZoomApps / Zoom Apps SDK experience?','Which 1–2 ZoomApp projects can be truthfully shared?','Is the role still hiring under Wise AI/Theris?','Current Pakistan remote eligibility and employment/contractor terms','Current salary and equity terms','Provider-specific AWS/GCP, healthtech, CV and signal-processing experience if relevant; do not infer from AI API work'],requirements=requirements,research=research,publicStaffRoute=research['contacts'],noMutations=True)
(root/'review.json').write_text(json.dumps(review,indent=2)+'\n')
print(json.dumps({'saved':['review.json','proposed-update.json'],'essentialUnknown':['ZoomApps experience'],'fit':'unknown','eligibility':'unknown'},indent=2))
